INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass IT-Firmen immer Preise untereinander absprechen dürfen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Preisabsprachen sind verboten"}, {"text": "Ja", "correct": false, "because": "Verstoß gegen Wettbewerbsrecht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich als IT-Dienstleister Angebote erstelle?', 3, '[{"text": "Eigenständige Preisgestaltung", "correct": true, "because": "Vermeidet Absprachen"}, {"text": "Kopieren von Konkurrenzpreisen", "correct": false, "because": "Riskiert Verstöße"}, {"text": "Schnellste Lieferung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Praktiken verhindern einen fairen Wettbewerb in der IT?', 5, '[{"text": "Marktaufteilung", "correct": true, "because": "Beschränkt Kundenwahl"}, {"text": "Preisabsprachen", "correct": true, "because": "Verzerrt Marktpreise"}, {"text": "Neue Features", "correct": false, "because": "Fördert Wettbewerb"}, {"text": "Kundensupport", "correct": false, "because": "Verbessert Service"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Preisabsprachen sind illegal. b) Marktbeherrschung ist immer verboten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Marktbeherrschung ist nur bei Missbrauch verboten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich als IT-Firma einen Vertrag mit einem Partner schließe?', 4, '[{"text": "Wettbewerbsregeln", "correct": false, "because": "Müssen geprüft werden"}, {"text": "Preisvereinbarungen", "correct": false, "because": "Können illegal sein"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Wettbewerbsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob kleine IT-Firmen Preisabsprachen machen dürfen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Firmen dürfen nicht absprachen"}, {"text": "Ja", "correct": false, "because": "Verbot gilt für alle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten verstößt gegen Wettbewerbsregeln?', 3, '[{"text": "Marktaufteilung mit Konkurrenten", "correct": true, "because": "Beschränkt Wettbewerb"}, {"text": "Werbung für Software", "correct": false, "because": "Erlaubt"}, {"text": "Rabattaktionen", "correct": false, "because": "Fördert Wettbewerb"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sichern fairen Wettbewerb in der IT?', 5, '[{"text": "Transparente Preise", "correct": true, "because": "Verhindert Absprachen"}, {"text": "Eigene Innovationen", "correct": true, "because": "Stärkt Wettbewerb"}, {"text": "Gleiche Hardware", "correct": false, "because": "Kein Wettbewerbsfaktor"}, {"text": "Einheitliche Designs", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Fusionen müssen geprüft werden. b) Rabatte sind immer illegal. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rabatte sind meist erlaubt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um als IT-Firma legal zu konkurrieren?', 4, '[{"text": "Kenntnis der Gesetze", "correct": false, "because": "Vermeidet Verstöße"}, {"text": "Eigene Preisgestaltung", "correct": false, "because": "Sichert Fairness"}, {"text": "Partnerabsprachen", "correct": true, "because": "Können illegal sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine marktbeherrschende Stellung immer ein Verstoß?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Missbrauch ist verboten"}, {"text": "Ja", "correct": false, "because": "Marktstellung allein ist legal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen hat ein Verstoß gegen Wettbewerbsregeln?', 4, '[{"text": "Bußgelder", "correct": true, "because": "Bestraft Verstöße"}, {"text": "Reputationsschaden", "correct": true, "because": "Beeinträchtigt Vertrauen"}, {"text": "Mehr Kunden", "correct": false, "because": "Eher Verlust"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass IT-Firmen Märkte frei aufteilen dürfen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Marktaufteilung ist illegal"}, {"text": "Ja", "correct": false, "because": "Verstoß gegen Gesetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was prüfe ich, bevor ich als IT-Firma mit einem Konkurrenten kooperiere?', 3, '[{"text": "Wettbewerbskonformität", "correct": true, "because": "Vermeidet Verstöße"}, {"text": "Gemeinsame Werbung", "correct": false, "because": "Nicht primär"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Preisvorgaben an Händler sind verboten. b) Innovationen sind illegal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Innovationen sind erlaubt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren fördern legalen Wettbewerb in der IT?', 5, '[{"text": "Unabhängige Preise", "correct": true, "because": "Verhindert Absprachen"}, {"text": "Kundenorientierung", "correct": true, "because": "Stärkt Markt"}, {"text": "Gleiche Software", "correct": false, "because": "Hemmung Innovation"}, {"text": "Einheitliche Verträge", "correct": false, "because": "Einschränkt Freiheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich als IT-Firma fair konkurriere?', 3, '[{"text": "Eigene Preisstrategie", "correct": false, "because": "Sichert Fairness"}, {"text": "Gesetzeskenntnis", "correct": false, "because": "Vermeidet Verstöße"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Wettbewerbsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Dürfen IT-Firmen Liefermengen mit Konkurrenten festlegen?', 3, '[{"text": "Nein", "correct": true, "because": "Verzerrt Wettbewerb"}, {"text": "Ja", "correct": false, "because": "Illegal"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Fusionen in der IT immer erlaubt sind?', 2, '[{"text": "Nein", "correct": true, "because": "Müssen geprüft werden"}, {"text": "Ja", "correct": false, "because": "Können Markt verzerren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten ist in der IT-Branche erlaubt?', 4, '[{"text": "Eigene Rabatte anbieten", "correct": true, "because": "Fördert Wettbewerb"}, {"text": "Preise mit Konkurrenten festlegen", "correct": false, "because": "Illegal"}, {"text": "Märkte aufteilen", "correct": false, "because": "Verboten"}]');
